//! The malicious corpus (`tests/fixtures/malicious/`, generated by
//! `tests/fixtures/ods/gen_fixtures.py`). Every input must be rejected (or
//! safely opened) quickly, without unbounded allocation.

#![allow(clippy::unwrap_used)] // tests may unwrap (docs/contributing.md)

mod common;

use std::io::Cursor;
use std::time::{Duration, Instant};

use common::read_fixture;
use tally_io_ods::{read_ods, Limits, OdsError};
use tally_model::WorkbookData;

fn read_with(rel: &str, limits: &Limits) -> (Result<WorkbookData, OdsError>, Duration) {
    let bytes = read_fixture(rel);
    let t = Instant::now();
    let r = read_ods(Cursor::new(bytes), limits);
    let t = t.elapsed();
    eprintln!(
        "TIMING {rel}: {t:?} -> {}",
        match &r {
            Ok(_) => "Ok".to_string(),
            Err(e) => e.to_string(),
        }
    );
    (r, t)
}

fn read(rel: &str) -> (Result<WorkbookData, OdsError>, Duration) {
    read_with(rel, &Limits::default())
}

fn limit_what(r: &Result<WorkbookData, OdsError>) -> &'static str {
    match r {
        Err(OdsError::LimitExceeded { what, .. }) => what,
        other => panic!("expected LimitExceeded, got {other:?}"),
    }
}

#[test]
fn zip_bomb_is_rejected_within_one_second() {
    // 1 GiB of zeros deflated to ~1 MB (ratio ~1000:1). The ratio guard trips
    // after ~10 MiB of output; the inflated size is never allocated.
    let (r, t) = read("malicious/zip-bomb.ods");
    assert_eq!(limit_what(&r), "compression ratio");
    assert!(t < Duration::from_secs(1), "took {t:?}");
}

#[test]
fn zip_bomb_hits_entry_cap_when_ratio_is_disabled() {
    let limits = Limits {
        max_ratio: u32::MAX,
        max_content_xml_bytes: 8 * 1024 * 1024,
        ..Limits::default()
    };
    let (r, t) = read_with("malicious/zip-bomb.ods", &limits);
    assert_eq!(limit_what(&r), "zip entry uncompressed bytes");
    assert!(t < Duration::from_secs(1), "took {t:?}");
}

#[test]
fn total_bytes_cap() {
    let limits = Limits {
        max_total_bytes: 1024,
        ..Limits::default()
    };
    let (r, _) = read_with("ods/libreoffice-style.ods", &limits);
    assert_eq!(limit_what(&r), "total uncompressed bytes");
}

