/// quick-xml itself never resolves external (or any DTD-declared) entities:
/// it reports the reference and leaves resolution to us.
#[test]
fn quick_xml_does_not_resolve_external_entities() {
    use quick_xml::events::Event;
    let doc = r#"<?xml version="1.0"?><!DOCTYPE x [<!ENTITY xxe SYSTEM "file:///etc/passwd"><!ENTITY int "INTERNAL">]><x>&xxe;&int;</x>"#;
    let mut reader = quick_xml::Reader::from_str(doc);
    let mut saw_doctype = false;
    let mut refs = Vec::new();
    let mut text = String::new();
    loop {
        match reader.read_event().unwrap() {
            Event::DocType(_) => saw_doctype = true,
            Event::GeneralRef(r) => refs.push(r.xml10_content().into_owned()),
            Event::Text(t) => text.push_str(&t.xml10_content()),
            Event::Eof => break,
            _ => {}
        }
    }
    assert!(saw_doctype);
    assert_eq!(refs, ["xxe", "int"]);
    assert!(!text.contains("root:"), "no file content");
    assert!(!text.contains("INTERNAL"), "no internal expansion either");
}

#[test]
fn traversal_entry_names_are_ignored() {
    // `../content.xml` (sheet "Evil") and `a/../../styles.xml` (a DOCTYPE)
    // are never looked at; the real content.xml opens.
    let (r, _) = read("malicious/path-traversal.ods");
    let wb = r.unwrap();
    assert_eq!(wb.sheets.len(), 1);
    assert_eq!(wb.sheets[0].name, "Good");
    assert!(!std::path::Path::new("/tmp/tally-evil.txt").exists());
}

#[test]
fn repeated_rows_bomb_hits_cell_cap_fast() {
    // 1,048,576 rows × 16,384 columns of a non-empty cell = 17 G cells.
    let (r, t) = read("malicious/repeat-bomb.ods");
    assert_eq!(limit_what(&r), "materialized cells");
    assert!(t < Duration::from_secs(2), "took {t:?}");
}

#[test]
fn repeat_is_capped_by_max_repeat() {
    // A repeated non-empty row is materialized at most max_repeat times.
    let limits = Limits {
        max_repeat: 10,
        ..Limits::default()
    };
    let (r, t) = read_with("malicious/repeat-bomb.ods", &limits);
    assert!(t < Duration::from_secs(2), "took {t:?}");
    let wb = r.unwrap();
    assert_eq!(wb.sheets[0].cells.len(), 10 * 16_384);
}

