#[test]
fn not_ods_inputs() {
    for f in [
        "malicious/not-a-zip.ods",
        "malicious/no-content.ods",
        "malicious/text-document.odt",
    ] {
        let (r, _) = read(f);
        assert!(matches!(r, Err(OdsError::NotOds)), "{f}: {r:?}");
    }
    assert!(matches!(
        read_ods(Cursor::new(Vec::new()), &Limits::default()),
        Err(OdsError::NotOds)
    ));
}

#[test]
fn cell_cap_applies_to_real_files() {
    let limits = Limits {
        max_cells: 10,
        ..Limits::default()
    };
    let (r, _) = read_with("ods/libreoffice-style.ods", &limits);
    assert_eq!(limit_what(&r), "materialized cells");
}

/// Cheap deterministic mutation fuzzing: truncations and byte flips of a real
/// fixture must never panic or hang.
#[test]
fn mutated_inputs_never_panic() {
    let base = read_fixture("ods/libreoffice-style.ods");
    let mut seed: u64 = 0x9e37_79b9_7f4a_7c15;
    let mut next = || {
        seed ^= seed << 13;
        seed ^= seed >> 7;
        seed ^= seed << 17;
        seed
    };
    let start = Instant::now();
    for len in (0..base.len()).step_by(97) {
        let _ = read_ods(Cursor::new(&base[..len]), &Limits::default());
    }
    for _ in 0..400 {
        let mut b = base.clone();
        for _ in 0..(1 + next() % 8) {
            let i = (next() % b.len() as u64) as usize;
            b[i] = next() as u8;
        }
        let _ = read_ods(Cursor::new(b), &Limits::default());
    }
    assert!(start.elapsed() < Duration::from_secs(20));
}
